import{describe,it,expect}from"vitest";import{INSTITUTIONS_DATA,INSTITUTION_CATEGORIES,filterInstitutions,getInstitutionsStats}from"../../frontend/government-institutions-explorer/script.js";describe("Government Institutions Dataset Completeness",()=>{it("contains exactly all 9 required institutions",()=>{expect(INSTITUTIONS_DATA.length).toBe(9);const t=INSTITUTIONS_DATA.map(t=>t.acronym);expect(t).toContain("RBI"),expect(t).toContain("SEBI"),expect(t).toContain("CBI"),expect(t).toContain("UPSC"),expect(t).toContain("ECI"),expect(t).toContain("CAG"),expect(t).toContain("NITI Aayog"),expect(t).toContain("FC"),expect(t).toContain("NHRC")}),it("every institution contains all 6 required detail fields",()=>{INSTITUTIONS_DATA.forEach((t,e)=>{expect(t,`Institution ${e} missing formation`).toHaveProperty("formation"),expect(t,`Institution ${e} missing headquarters`).toHaveProperty("headquarters"),expect(t,`Institution ${e} missing currentHead`).toHaveProperty("currentHead"),expect(t,`Institution ${e} missing responsibilities`).toHaveProperty("responsibilities"),expect(t,`Institution ${e} missing structure`).toHaveProperty("structure"),expect(t,`Institution ${e} missing funFacts`).toHaveProperty("funFacts"),expect(Array.isArray(t.responsibilities)).toBe(!0),expect(t.responsibilities.length).toBeGreaterThanOrEqual(3),expect(Array.isArray(t.funFacts)).toBe(!0),expect(t.funFacts.length).toBeGreaterThanOrEqual(2)})})}),describe("Filter & Search Operations",()=>{it("filters institutions by search query matching name or acronym",()=>{const t=filterInstitutions(INSTITUTIONS_DATA,"All Categories","rbi");expect(t.length).toBe(1),expect(t[0].fullName).toContain("Reserve Bank");const e=filterInstitutions(INSTITUTIONS_DATA,"All Categories","New Delhi");expect(e.length).toBeGreaterThanOrEqual(7)}),it("filters institutions by category tab",()=>{const t=filterInstitutions(INSTITUTIONS_DATA,"Constitutional","");expect(t.length).toBe(4);const e=filterInstitutions(INSTITUTIONS_DATA,"Statutory","");expect(e.length).toBe(3)}),it("computes institution summary stats correctly",()=>{const t=getInstitutionsStats();expect(t.totalInstitutions).toBe(9),expect(t.constitutionalCount).toBe(4),expect(t.statutoryCount).toBe(3),expect(t.executiveCount).toBe(2)})});